import { ObjectSchema } from "./utils/plugin-options-schema-joi-type"

interface ITestPluginOptionsSchemaReturnType {
  isValid: boolean
  errors: Array<string>
}

/**
 * A utility to help plugin authors test their `pluginOptionsSchema` against a
 * set of options without running a full Gatsby build.
 *
 * Only the fields present in `pluginOptions` are validated, so plugin authors
 * can test a partial set of options even when other fields are required by the
 * schema.
 */
export function testPluginOptionsSchema(
  pluginSchemaFunction: ({ Joi }: { Joi: any }) => ObjectSchema,
  pluginOptions: object
): ITestPluginOptionsSchemaReturnType {
  const pluginSchema = pluginSchemaFunction({ Joi })

  // Make every field that isn't part of the passed options optional so that
  // required fields the author didn't include don't produce errors.
  const describedKeys = Object.keys(pluginSchema.describe().keys || {})
  const keysToMakeOptional = describedKeys.filter(
    key => !(key in pluginOptions)
  )

  const schemaToValidate = keysToMakeOptional.length
    ? pluginSchema.fork(keysToMakeOptional, schema => schema.optional())
    : pluginSchema

  const { error } = schemaToValidate.validate(pluginOptions, {
    // Show all errors at once, rather than only the first one every time
    abortEarly: false,
    // Only label errors with the key rather than the full path so array item
    // errors read as `"[0]"` instead of `"field[0]"`.
    errors: { label: `key` },
    // The external (async) rules can't run during a synchronous validation
    externals: false,
  })

  if (!error) {
    return { isValid: true, errors: [] }
  }

  // Group error details by their top-level field so that all the failing items
  // of an array field can be concatenated into a single error message.
  const detailsByField: Map<string, Array<string>> = new Map()
  const errors: Array<string> = []

  error.details.forEach(detail => {
    const [topLevelKey] = detail.path

    // Scalar/top-level errors already contain the field name in the message.
    if (detail.path.length <= 1) {
      errors.push(detail.message)
      return
    }

    const fieldKey = String(topLevelKey)
    const messages = detailsByField.get(fieldKey) || []
    messages.push(detail.message)
    detailsByField.set(fieldKey, messages)
  })

  detailsByField.forEach((messages, fieldKey) => {
    errors.push(`"${fieldKey}" ${messages.join(`. `)}`)
  })

  return {
    isValid: false,
    errors,
  }
}
